-- Reconciliation → Discrepancy Report → Lines
-- Route: C1_RECONCILIATION_CHAR (CHAR_TYPE_CD='CMDSCREP', SRCH_CHAR_VAL=DISCREPANCY_RPT_ID)
SELECT    r.RECONCILIATION_ID,    r.RECON_TYPE_CD,    r.EXTERNAL_REF_ID,    r.BO_STATUS_CD                      AS recon_status,    -- Discrepancy report header    dr.DISCREPANCY_RPT_ID,    dr.DSC_RPT_TYPE_CD                  AS report_type,    dr.BO_STATUS_CD                     AS report_status,    dr.BO_STATUS_REASON_CD             AS report_status_reason,    dr.CRE_DTTM                        AS report_created,    dr.STATUS_UPD_DTTM                 AS report_last_updated,    -- Discrepancy line detail    ln.DR_SEQNO                        AS line_seq,    ln.ACCT_ID,    ln.ACCT_NBR,    ln.ACCT_NBR_TYPE_CD,    ln.POLICY_NBR,    ln.PLAN_NBR,    ln.PER_ID_NBR,    ln.ID_TYPE_CD,    ln.ENTITY_NAME                     AS member_name,    ln.COV_START_DT                    AS coverage_start,    ln.COV_END_DT                      AS coverage_end,    ln.BILLED_AMT                      AS billed_amount,    ln.PAID_AMT                        AS paid_amount,    ln.DSC_AMT                         AS discrepancy_amount,    ln.DSC_CAT_FLG                     AS discrepancy_category,    ln.COMMENTS,    ln.HEALTH_PLAN_CD,    ln.PAYMENT_TYPE,    ln.HIOS_IDFROM   C1_RECONCILIATION        rLEFT JOIN   C1_RECONCILIATION_CHAR   rc   ON  rc.RECONCILIATION_ID  = r.RECONCILIATION_ID                                     AND rc.CHAR_TYPE_CD        = 'CMDSCREP'LEFT JOIN   C1_DISCREPANCY_RPT       dr   ON  dr.DISCREPANCY_RPT_ID  = rc.SRCH_CHAR_VALLEFT JOIN   C1_DISCREPANCY_RPT_LN    ln   ON  ln.DISCREPANCY_RPT_ID  = dr.DISCREPANCY_RPT_IDWHERE  r.RECONCILIATION_ID = '925548106645'ORDER BY ln.DR_SEQNO;
